#pragma once

#include <cstdint>
#include <string>
#include <string_view>
#include <vector>
#include <unordered_map>
#include <nlohmann/json.hpp>
#include <algorithm>
#include <cmath>

namespace ptv { class World; struct CTag; }

namespace hover_internal {

struct HoverParams {
    float hover_max_speed_mps = 1.2f;
    float hover_accel_tau_s = 0.12f;
    float altitude_nudge_step_m = 0.25f;
    float altitude_min_m = 0.5f;
    float altitude_max_m = 25.0f;
    float damping_tau_s = 0.20f;
    bool  comfort_hand_stabilize = true;
    // Scene allowlist; empty means allowed everywhere
    std::vector<std::string> allowed_in_scenes; 
};

struct FrameInput {
    // Buttons and sticks from the harness via params_json on the binding entry each frame
    bool a_pressed = false;         // rising-edge press this frame
    float left_x = 0.0f;            // -1..1
    float left_y = 0.0f;            // -1..1 (forward)
    float right_y = 0.0f;           // -1..1 (up when > 0)
    bool altitude_assist = true;    // allow right stick vertical nudges
    std::string scene_id;           // optional, for allowlist checks
};

struct HoverState {
    bool active = false;
    float t_now = 0.0f;                 // local time accumulator (s)
    float last_a_press_t = -1e9f;       // last press time (s)
    float a_double_window_s = 0.35f;    // double-tap window
    float hum_pulse_timer = 0.0f;       // for periodic hover hum haptics

    // velocity on XZ (world)
    float vx = 0.0f;
    float vz = 0.0f;

    // altitude baseline+current clamp
    float altitude_baseline_y = 0.0f;   // set on enter
};

inline float clampf(float v, float lo, float hi) {
    return std::max(lo, std::min(hi, v));
}

inline void upsert_tag(ptv::World& w, std::uint32_t e, const std::string& key, const std::string& value_json);
inline void remove_tag_with_prefix(ptv::World& w, std::uint32_t e, std::string_view prefix);

// Params parsing helpers
inline HoverParams parse_params_object(const nlohmann::json& p) {
    HoverParams hp;
    if (p.is_object()) {
        hp.hover_max_speed_mps = p.value("hover_max_speed_mps", hp.hover_max_speed_mps);
        hp.hover_accel_tau_s = p.value("hover_accel_tau_s", hp.hover_accel_tau_s);
        hp.altitude_nudge_step_m = p.value("altitude_nudge_step_m", hp.altitude_nudge_step_m);
        hp.damping_tau_s = p.value("damping_tau_s", hp.damping_tau_s);
        hp.comfort_hand_stabilize = p.value("comfort_hand_stabilize", hp.comfort_hand_stabilize);
        if (p.contains("altitude_bounds_m") && p["altitude_bounds_m"].is_array() && p["altitude_bounds_m"].size() == 2) {
            hp.altitude_min_m = p["altitude_bounds_m"][0].get<float>();
            hp.altitude_max_m = p["altitude_bounds_m"][1].get<float>();
            if (hp.altitude_min_m > hp.altitude_max_m) std::swap(hp.altitude_min_m, hp.altitude_max_m);
        }
        if (p.contains("allowed_in_scenes") && p["allowed_in_scenes"].is_array()) {
            for (auto& s : p["allowed_in_scenes"]) if (s.is_string()) hp.allowed_in_scenes.push_back(s.get<std::string>());
        }
    }
    return hp;
}

// First-order response toward target with time-constant tau
inline float lowpass_step(float current, float target, float dt, float tau) {
    if (tau <= 1e-5f) return target;
    float a = clampf(dt / tau, 0.0f, 1.0f);
    return current + a * (target - current);
}

// Reads per-frame inputs from CMechanicBinding entry for this mechanic id.
FrameInput read_frame_input(ptv::World& w, std::uint32_t e, const char* mechanic_id);

// Haptics helpers (strings from dependency exports; no header includes across tasks)
static constexpr const char* kHapticsPublishPrefix = "haptics.publish:";
static constexpr const char* kPatternHoverLight = "hover_light";
static constexpr const char* kPatternClick = "bolt_fire_sharp"; // reuse as toggle click

inline void publish_haptics(ptv::World& w, std::uint32_t e, const std::string& pattern_id, const char* hand, float amp, float dur_s);

// Locomotion interop via tags
// We write lightweight tags other systems can read:
//  - "locomotion.mode:{\"state\":\"hover\"}"
//  - "locomotion.velocity:{\"vx\":...,\"vy\":...,\"vz\":...}"
//  - "aim.stabilizer:{\"enabled\":true,\"strength\":0.6}"
inline void write_hover_mode_tag(ptv::World& w, std::uint32_t e, bool active);
inline void write_velocity_tag(ptv::World& w, std::uint32_t e, float vx, float vy, float vz);
inline void write_aim_stabilizer_tag(ptv::World& w, std::uint32_t e, bool enabled, float strength);

// Scene allowlist check
inline bool scene_allowed(const HoverParams& hp, const std::string& scene_id) {
    if (hp.allowed_in_scenes.empty()) return true;
    return std::find(hp.allowed_in_scenes.begin(), hp.allowed_in_scenes.end(), scene_id) != hp.allowed_in_scenes.end();
}

} // namespace hover_internal

#include "ptv/ecs/World.h"
#include "hover_mode_shared.h"

#include <entt/entt.hpp>
#include <string>

using nlohmann::json;

namespace hover_internal {

// World helpers declared in shared
inline void upsert_tag(ptv::World& w, std::uint32_t e, const std::string& key, const std::string& value_json) {
    if (!w.valid(e)) return;
    if (!w.has<ptv::CTag>(e)) {
        w.emplace_or_replace<ptv::CTag>(e, ptv::CTag{});
    }
    auto& vec = w.get<ptv::CTag>(e).tags;
    // replace if same prefix exists, else push
    auto prefix = key;
    bool replaced = false;
    for (auto& s : vec) {
        if (s.rfind(prefix, 0) == 0) { // starts with
            s = key + value_json;
            replaced = true;
            break;
        }
    }
    if (!replaced) vec.push_back(key + value_json);
}

inline void remove_tag_with_prefix(ptv::World& w, std::uint32_t e, std::string_view prefix) {
    if (!w.valid(e) || !w.has<ptv::CTag>(e)) return;
    auto& vec = w.get<ptv::CTag>(e).tags;
    vec.erase(std::remove_if(vec.begin(), vec.end(), [&](const std::string& s){ return s.rfind(prefix.data(), 0) == 0; }), vec.end());
}

FrameInput read_frame_input(ptv::World& w, std::uint32_t e, const char* mechanic_id) {
    FrameInput fi;
    // Default scene id empty; if the entity has a tag "scene_id:<id>", consume it
    if (w.has<ptv::CTag>(e)) {
        const auto& tags = w.get<ptv::CTag>(e).tags;
        for (const auto& s : tags) {
            constexpr const char* kScenePrefix = "scene.id:";
            if (s.rfind(kScenePrefix, 0) == 0) {
                fi.scene_id = s.substr(std::char_traits<char>::length(kScenePrefix));
                break;
            }
        }
    }

    // Scan CMechanicBinding to find our entry and parse params_json (serialised each frame by the harness)
    auto& reg = w.registry();
    auto view = reg.view<ptv::CMechanicBinding>();
    for (auto ent : view) {
        auto& bind = view.get<ptv::CMechanicBinding>(ent);
        for (auto& entry : bind.entries) {
            if (entry.id == mechanic_id) {
                auto j = json::parse(entry.params_json, nullptr, /*allow_exceptions=*/false);
                if (j.is_object()) {
                    fi.a_pressed = j.value("a_button_press", false);
                    if (j.contains("left_stick") && j["left_stick"].is_array() && j["left_stick"].size() == 2) {
                        fi.left_x = j["left_stick"][0].get<float>();
                        fi.left_y = j["left_stick"][1].get<float>();
                    } else {
                        fi.left_x = j.value("left_x", 0.0f);
                        fi.left_y = j.value("left_y", 0.0f);
                    }
                    fi.right_y = j.value("right_y", j.value("right_stick_y", 0.0f));
                    fi.altitude_assist = j.value("altitude_assist", true);
                    fi.scene_id = j.value("scene_id", fi.scene_id);
                }
                return fi; // first match is enough
            }
        }
    }
    return fi;
}

inline void publish_haptics(ptv::World& w, std::uint32_t e, const std::string& pattern_id, const char* hand, float amp, float dur_s) {
    // Emit a publish tag on this entity; the haptics manager listens globally
    nlohmann::json j;
    j["pattern_id"] = pattern_id;
    j["hand"] = hand;
    j["intensity_scale"] = amp;
    j["duration_s"] = dur_s;
    upsert_tag(w, e, kHapticsPublishPrefix, j.dump());
}

inline void write_hover_mode_tag(ptv::World& w, std::uint32_t e, bool active) {
    nlohmann::json j; j["state"] = active ? "hover" : "off";
    upsert_tag(w, e, std::string("locomotion.mode:"), j.dump());
}

inline void write_velocity_tag(ptv::World& w, std::uint32_t e, float vx, float vy, float vz) {
    nlohmann::json j; j["vx"] = vx; j["vy"] = vy; j["vz"] = vz;
    upsert_tag(w, e, std::string("locomotion.velocity:"), j.dump());
}

inline void write_aim_stabilizer_tag(ptv::World& w, std::uint32_t e, bool enabled, float strength) {
    nlohmann::json j; j["enabled"] = enabled; j["strength"] = strength;
    upsert_tag(w, e, std::string("aim.stabilizer:"), j.dump());
}

} // namespace hover_internal

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <cmath>
#include <unordered_map>
#include <string>

#include "hover_mode_shared.h"

using nlohmann::json;
using namespace hover_internal;

namespace ptv {

class HoverModeMechanic : public IMechanic {
public:
    void on_attach(World& w, std::uint32_t e, const json& params) override {
        (void)w; (void)e;
        params_ = parse_params_object(params);
        // Fresh state; baseline captured on first activation
    }

    void on_update(World& w, std::uint32_t e, float dt) override {
        auto& st = state_[e];
        st.t_now += (dt > 0.0f ? dt : w.delta_time());

        // Inputs each frame
        FrameInput in = read_frame_input(w, e, id().c_str());

        // Respect scene allowlist if provided
        bool allowed = scene_allowed(params_, in.scene_id);

        // Double-tap A to toggle
        if (in.a_pressed) {
            if (st.t_now - st.last_a_press_t <= st.a_double_window_s && allowed) {
                st.active = !st.active;
                // Toggle haptics click
                publish_haptics(w, e, kPatternClick, "right", 0.35f, 0.05f);
                publish_haptics(w, e, kPatternClick, "left", 0.25f, 0.05f);
                if (st.active) {
                    // Enter hover: instant brake, capture baseline, enable stabilizer tag
                    st.vx = 0.0f; st.vz = 0.0f;
                    if (w.has<CTransform>(e)) st.altitude_baseline_y = w.get<CTransform>(e).t.position.y;
                    write_aim_stabilizer_tag(w, e, params_.comfort_hand_stabilize, params_.comfort_hand_stabilize ? 0.6f : 0.0f);
                    write_hover_mode_tag(w, e, true);
                    publish_haptics(w, e, kPatternHoverLight, "both", 0.55f, 0.12f);
                } else {
                    // Exit hover: zero velocity, disable stabilizer, clear mode
                    st.vx = 0.0f; st.vz = 0.0f;
                    write_velocity_tag(w, e, 0.0f, 0.0f, 0.0f);
                    write_aim_stabilizer_tag(w, e, false, 0.0f);
                    write_hover_mode_tag(w, e, false);
                }
            }
            st.last_a_press_t = st.t_now;
        }

        if (!st.active || !allowed) {
            // Drift to stop if we somehow had residual velocity
            if ((std::fabs(st.vx) + std::fabs(st.vz)) > 1e-4f) {
                st.vx = lowpass_step(st.vx, 0.0f, dt, params_.damping_tau_s);
                st.vz = lowpass_step(st.vz, 0.0f, dt, params_.damping_tau_s);
                write_velocity_tag(w, e, st.vx, 0.0f, st.vz);
            }
            return;
        }

        // While active: desired lateral velocity from left stick (world XZ). Clamp to max speed.
        float mag = std::sqrt(in.left_x*in.left_x + in.left_y*in.left_y);
        if (mag > 1.0f) { in.left_x /= mag; in.left_y /= mag; }
        float target_vx = params_.hover_max_speed_mps * in.left_x;
        float target_vz = params_.hover_max_speed_mps * in.left_y;

        // Accelerate / decelerate with tau
        st.vx = lowpass_step(st.vx, target_vx, dt, params_.hover_accel_tau_s);
        st.vz = lowpass_step(st.vz, target_vz, dt, params_.hover_accel_tau_s);

        // Extra damping toward zero when sticks released
        if (mag < 0.05f) {
            st.vx = lowpass_step(st.vx, 0.0f, dt, params_.damping_tau_s);
            st.vz = lowpass_step(st.vz, 0.0f, dt, params_.damping_tau_s);
        }

        // Apply to transform position each tick (local, since no physics integrator exposed here)
        if (w.has<CTransform>(e)) {
            auto& tr = w.get<CTransform>(e).t;
            tr.position.x += st.vx * dt;
            tr.position.z += st.vz * dt;

            // Altitude nudge by right stick if assist
            float vy = 0.0f;
            if (in.altitude_assist) {
                const float thr = 0.60f;
                if (in.right_y > thr) {
                    tr.position.y += params_.altitude_nudge_step_m;
                } else if (in.right_y < -thr) {
                    tr.position.y -= params_.altitude_nudge_step_m;
                }
                // Clamp within baseline +/- bounds
                float minY = st.altitude_baseline_y + params_.altitude_min_m;
                float maxY = st.altitude_baseline_y + params_.altitude_max_m;
                tr.position.y = clampf(tr.position.y, minY, maxY);
                // vy only used for tag telemetry this frame (0 except when we stepped)
                // We approximate using difference to baseline sign if needed; keep 0 for now.
                vy = 0.0f;
            }

            // Write velocity telemetry tag for interop
            write_velocity_tag(w, e, st.vx, 0.0f /*vy*/, st.vz);
        }

        // Periodic subtle hover hum while active
        st.hum_pulse_timer += dt;
        if (st.hum_pulse_timer >= 0.8f) {
            st.hum_pulse_timer = 0.0f;
            publish_haptics(w, e, kPatternHoverLight, "both", 0.25f, 0.06f);
        }
    }

    void on_detach(World& w, std::uint32_t e) override {
        // Clean up our tags
        remove_tag_with_prefix(w, e, "locomotion.mode:");
        remove_tag_with_prefix(w, e, "locomotion.velocity:");
        remove_tag_with_prefix(w, e, "aim.stabilizer:");
        state_.erase(e);
    }

    std::string id() const override { return "generated.hover_mode_mechanic"; }

private:
    HoverParams params_{};
    std::unordered_map<std::uint32_t, HoverState> state_;
};

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.hover_mode_mechanic", ptv::HoverModeMechanic)

